    js: `const root=document.querySelector('.saas-page'),nav=document.querySelector('.saas-nav'),menu=document.querySelector('.saas-menu'),status=document.querySelector('.page-status'),tabs=[...document.querySelectorAll('.saas-tabs [role=tab]')],modeContent={observe:{index:'01 / OBSERVE',title:'Bring the evidence<br>into one frame.',copy:'Collect notes, calls and product signals without losing the source or the question they answer.',items:['Evidence linked to its source','Confidence visible at a glance','Async context for every teammate']},decide:{index:'02 / DECIDE',title:'Make the trade-off<br>visible to everyone.',copy:'Frame options, constraints and ownership in one durable decision record.',items:['Alternatives compared directly','Assumptions named before build','One accountable next action']},learn:{index:'03 / LEARN',title:'Close the loop<br>after release.',copy:'Connect outcomes back to the original evidence and keep the next question alive.',items:['Outcome health at a glance','Unexpected signals captured','Learning linked to the release']}};menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.classList.toggle('open',open)});function selectMode(index,focus=false){const tab=tabs[index],item=modeContent[tab.dataset.mode];tabs.forEach((node,i)=>{node.setAttribute('aria-selected',String(i===index));node.tabIndex=i===index?0:-1});document.querySelector('.product-index').textContent=item.index;document.querySelector('.saas-product-copy h3').innerHTML=item.title;document.querySelector('.saas-product-copy p').textContent=item.copy;document.querySelector('.saas-product-copy ul').innerHTML=item.items.map(value=>'<li>'+value+'</li>').join('');document.querySelector('.board-toolbar>span').textContent=tab.textContent.trim()+' workspace';if(focus)tab.focus()}tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectMode(index));tab.addEventListener('keydown',event=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(event.key))return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;selectMode(next,true)})});document.querySelectorAll('a[href^="#"]').forEach(link=>link.addEventListener('click',event=>{const target=document.querySelector(link.getAttribute('href'));if(!target)return;event.preventDefault();root.scrollTo({top:target.offsetTop-(nav.offsetHeight||0),behavior:reduced.matches?'instant':'smooth'})}));document.querySelectorAll('.saas-start,.saas-primary,.saas-final-button,.saas-login').forEach(button=>button.addEventListener('click',()=>{status.textContent=button.textContent.trim()+' selected — local product demo.';root.scrollTo({top:root.scrollHeight,behavior:reduced.matches?'instant':'smooth'})}));`,
    logic: 'A complete fictional SaaS page connects sticky navigation, conversion hero, product evidence, customer proof, interactive three-mode product tour, outcomes, testimonial and closing CTA. The tablist supports roving focus and Arrow/Home/End keys. Internal links scroll the iframe-owned document; the mobile menu and CTAs update explicit local status. Card mode intentionally shows the full hero and product surface rather than shrinking the complete long page.',
    acceptance: 'The page reads as one coherent product story from promise through product, evidence and CTA. Product tabs change meaningful content, navigation anchors work inside the page, the mobile menu is usable, and no action claims to create an account or send data.',
